import { querySolveCount } from '@/api/xcnanr/statisticalAnalysis'
import xtTreeLzaySelect from '@/components/xtTreeLzaySelect/index.vue'

export default {
  name: 'index',
  components: { xtTreeLzaySelect },
  data() {
    return {
      workTimes: [],
      searchForm: {
        pageNumber: 1,
        pageSize: 10,
        startDate: undefined,
        endDate: undefined,
        companyId: undefined
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      repairStatusList: [],
      auth: ''
    }
  },
  created() {},
  mounted() {
    this.initSearchForm()
    this.$nextTick(() => {
      // this.setTableHeight()
    })
    this.setPageContentHeight()
    this.getList()
  },
  methods: {
    /**
     * 查询
     */
    queryEvent() {
      this.searchForm.pageNumber = 1
      this.searchForm.pageSize = 10
      this.getList()
    },
    /**
     * 重置
     */
    resetEvent() {
      this.initSearchForm()
      this.getList()
    },
    initSearchForm() {
      this.searchForm = {
        pageNumber: 1,
        pageSize: 10,
        startDate: undefined,
        endDate: undefined,
        companyId: undefined
      }
    },
    getCompanyItem(val) {
      this.searchForm.companyId = val.id
      this.searchForm.companyName = val.fullName
      this.$forceUpdate()
    },
    /**
     * 获取表格数据
     */
    getList() {
      this.tableLoading = true
      this.tableLoading = true
      // 给查询时间段赋值
      if (this.searchForm.workTimes && this.searchForm.workTimes.length > 0) {
        this.searchForm.startDate = this.searchForm.workTimes[0] + ' 00:00:00'
        this.searchForm.endDate = this.searchForm.workTimes[1] + ' 23:59:59'
      } else {
        this.searchForm.startDate = null
        this.searchForm.endDate = null
      }
      querySolveCount(this.searchForm).then(res => {
        this.tableData = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      }).catch(() => {
        this.tableLoading = false
      })
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = (bodyBox[0].offsetHeight - 50) + 'px'
    },
    selectionChange(selection) {
      this.selectionList = selection.map(item => item.id)
    }
  }
}
